#ifndef TINYML_MODEL_H
#define TINYML_MODEL_H
#include <stdint.h>
// Generated by train_model.py. Feature order: severity, deadline, event_type.
// Output class: 1=CRITICAL, 2=HIGH, 3=NORMAL.
static uint8_t predictPriority(const uint8_t features[3]) {
  if (features[0] <= 0.5f) {
    if (features[1] <= 0.5f) {
      if (features[2] <= 0.5f) {
        return 3;
      } else {
        return 2;
      }
    } else {
      return 3;
    }
  } else {
    if (features[1] <= 0.5f) {
      if (features[0] <= 1.5f) {
        if (features[2] <= 1.5f) {
          return 2;
        } else {
          return 1;
        }
      } else {
        return 1;
      }
    } else {
      if (features[1] <= 1.5f) {
        if (features[0] <= 1.5f) {
          return 2;
        } else {
          if (features[2] <= 0.5f) {
            return 2;
          } else {
            return 1;
          }
        }
      } else {
        if (features[0] <= 1.5f) {
          if (features[2] <= 1.5f) {
            return 3;
          } else {
            return 2;
          }
        } else {
          return 2;
        }
      }
    }
  }
}
#endif
